-- Article publication must remain isolated from browser writes and public reads.
if (select count(*) from pg_class where oid in ('public.articles'::regclass,'public.article_companies'::regclass) and relrowsecurity) <> 2
or (select count(*) from pg_policies where schemaname='public' and tablename in ('articles','article_companies')) <> 2
or (select count(*) from pg_policies where schemaname='public' and tablename in ('articles','article_companies')
  and roles=array['authenticated']::name[] and cmd='SELECT' and permissive='PERMISSIVE' and qual='is_admin()') <> 2
or has_table_privilege('anon','public.articles','SELECT,INSERT,UPDATE,DELETE')
or has_table_privilege('anon','public.article_companies','SELECT,INSERT,UPDATE,DELETE')
or has_table_privilege('authenticated','public.articles','INSERT,UPDATE,DELETE')
or has_table_privilege('authenticated','public.article_companies','INSERT,UPDATE,DELETE')
or has_function_privilege('anon','public.save_article_draft(uuid,text,jsonb,uuid[],bigint)','EXECUTE')
or has_function_privilege('anon','public.set_article_publication(uuid,bigint,boolean)','EXECUTE')
or has_function_privilege('authenticated','public.read_published_articles()','EXECUTE')
or not has_function_privilege('service_role','public.read_published_articles()','EXECUTE')
then raise exception 'HW_BASELINE_MISMATCH'; end if;
